import { Component, OnInit } from '@angular/core';
import { CommonModule, CurrencyPipe } from '@angular/common';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { ActivatedRoute, RouterModule } from '@angular/router';
import { TransactionService } from '../../services/transaction.service';
import { AccountService } from '../../services/account.service';
import { Account } from '../../models/account.model';
import { TransactionRecord } from '../../models/transaction.model';
import { ErrorInfo } from '../../models/error-info.model';

@Component({
  selector: 'app-fund-transfer',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule, RouterModule, CurrencyPipe],
  templateUrl: './fund-transfer.component.html',
  styleUrls: ['./fund-transfer.component.css']
})
export class FundTransferComponent implements OnInit {
  transferForm!: FormGroup;
  accounts: Account[] = [];
  selectedAccount: Account | null = null;

  // Real-time dynamic discount calculations
  grossAmount = 0;
  discount = 0;
  netAmount = 0;
  isDiscountEligible = false;
  hasInsufficientBalance = false;

  isSubmitting = false;
  successMessage: string | null = null;
  errorMessage: string | null = null;
  completedTransaction: TransactionRecord | null = null;

  constructor(
    private fb: FormBuilder,
    private route: ActivatedRoute,
    private transactionService: TransactionService,
    private accountService: AccountService
  ) {}

  ngOnInit(): void {
    this.initForm();
    this.loadAccounts();

    // Listen to amount changes for dynamic real-time discount calculation
    this.transferForm.get('amount')?.valueChanges.subscribe(val => {
      this.recalculateDiscountAndBalance(val);
    });

    // Listen to source account selection changes for balance checking
    this.transferForm.get('sourceAccountNumber')?.valueChanges.subscribe(accNum => {
      this.selectedAccount = this.accounts.find(a => a.accountNumber === accNum) || null;
      this.recalculateDiscountAndBalance(this.transferForm.get('amount')?.value);
    });
  }

  private initForm(): void {
    const prefillSource = this.route.snapshot.queryParams['source'] || '';

    this.transferForm = this.fb.group({
      sourceAccountNumber: [prefillSource, [Validators.required, Validators.pattern('^[0-9]{12}$')]],
      destinationAccountNumber: ['', [Validators.required, Validators.pattern('^[0-9]{12}$')]],
      amount: [
        '',
        [
          Validators.required,
          Validators.min(0.01)
        ]
      ],
      remarks: ['']
    });
  }

  private loadAccounts(): void {
    this.accountService.getAccountsByCustomerId(1).subscribe({
      next: (accs) => {
        this.accounts = accs;
        if (this.accounts.length > 0 && !this.transferForm.get('sourceAccountNumber')?.value) {
          this.transferForm.patchValue({ sourceAccountNumber: this.accounts[0].accountNumber });
          this.selectedAccount = this.accounts[0];
        }
      },
      error: () => {
        // Fallback demo accounts
        this.accounts = [
          { accountId: 1, accountNumber: '100000000001', customerId: 1, accountType: 'SAVINGS', balance: 1000.00, status: 'ACTIVE' },
          { accountId: 2, accountNumber: '100000000002', customerId: 1, accountType: 'CHECKING', balance: 2500.00, status: 'ACTIVE' }
        ];
        this.selectedAccount = this.accounts[0];
        this.transferForm.patchValue({ sourceAccountNumber: this.accounts[0].accountNumber });
      }
    });
  }

  recalculateDiscountAndBalance(rawAmount: any): void {
    const amt = Number(rawAmount) || 0;
    this.grossAmount = amt;

    // BR-03 & BR-04: Dynamic Discount Calculation (> 500 Rule)
    if (amt > 500) {
      this.isDiscountEligible = true;
      this.discount = Math.round(amt * 0.05 * 100) / 100; // 5% discount rounded
      this.netAmount = Math.round((amt - this.discount) * 100) / 100;
    } else {
      this.isDiscountEligible = false;
      this.discount = 0;
      this.netAmount = amt;
    }

    // Dynamic Balance Verification
    if (this.selectedAccount && this.netAmount > Number(this.selectedAccount.balance)) {
      this.hasInsufficientBalance = true;
    } else {
      this.hasInsufficientBalance = false;
    }
  }

  get f() {
    return this.transferForm.controls;
  }

  onSubmit(): void {
    if (this.transferForm.invalid || this.hasInsufficientBalance) {
      this.transferForm.markAllAsTouched();
      return;
    }

    const source = this.transferForm.value.sourceAccountNumber;
    const dest = this.transferForm.value.destinationAccountNumber;

    // Client-side self transfer check
    if (source === dest) {
      this.errorMessage = '[ERR_SELF_TRANSFER_PROHIBITED] Source and destination account numbers cannot be identical.';
      return;
    }

    this.isSubmitting = true;
    this.successMessage = null;
    this.errorMessage = null;

    const transferPayload: TransactionRecord = {
      sourceAccountNumber: source,
      destinationAccountNumber: dest,
      grossAmount: this.grossAmount,
      discount: this.discount,
      netAmount: this.netAmount,
      transactionType: 'TRANSFER',
      status: 'SUCCESS'
    };

    this.transactionService.transferFunds(transferPayload).subscribe({
      next: (res: TransactionRecord) => {
        this.isSubmitting = false;
        this.completedTransaction = res;
        this.successMessage = `Fund transfer executed successfully! Transaction Ref: #${res.transactionId || 'SUCCESS'}`;

        // Update local balance
        if (this.selectedAccount) {
          this.selectedAccount.balance -= this.netAmount;
        }

        this.transferForm.get('destinationAccountNumber')?.reset();
        this.transferForm.get('amount')?.reset();
        this.grossAmount = 0;
        this.discount = 0;
        this.netAmount = 0;
      },
      error: (err) => {
        this.isSubmitting = false;
        // Parse InfyBankException ErrorInfo envelope from backend
        if (err.error && err.error.errorMessage) {
          const errorInfo: ErrorInfo = err.error;
          this.errorMessage = `[${errorInfo.errorCode || 'ERR_TRANSFER_REJECTED'}] ${errorInfo.errorMessage}`;
        } else {
          this.errorMessage = 'An unexpected network error occurred while routing through API Gateway (Port 8080).';
        }
      }
    });
  }

  dismissAlert(): void {
    this.successMessage = null;
    this.errorMessage = null;
  }
}
<div class="container py-4">
  <div class="row justify-content-center">
    <div class="col-lg-8 col-md-10">

      <div class="card shadow-sm border-0 rounded-4 overflow-hidden">
        <!-- Header -->
        <div class="card-header bg-gradient-transfer text-white p-4">
          <div class="d-flex align-items-center justify-content-between">
            <div>
              <span class="badge bg-white text-dark px-3 py-1 mb-2 fw-semibold">Instant Inter-Bank Transfer</span>
              <h3 class="mb-1 fw-bold text-white">Transfer Funds</h3>
              <p class="mb-0 text-white-50 small">Double-entry ledger transfer with real-time promotional discount computation</p>
            </div>
            <div class="rounded-circle bg-white bg-opacity-25 p-3 text-white">
              <i class="bi bi-arrow-left-right fs-2"></i>
            </div>
          </div>
        </div>

        <div class="card-body p-4 p-md-5">

          <!-- Success Alert -->
          <div *ngIf="successMessage" class="alert alert-success alert-dismissible fade show border-0 rounded-3 d-flex align-items-center" role="alert">
            <i class="bi bi-check-circle-fill fs-4 me-3 text-success"></i>
            <div class="flex-grow-1">
              <strong>Transfer Successful!</strong>
              <div class="small">{{ successMessage }}</div>
              <div *ngIf="completedTransaction" class="mt-2 small text-muted">
                Gross: <strong>{{ completedTransaction.grossAmount | currency:'USD':'symbol':'1.2-2' }}</strong> | 
                Discount: <span class="badge bg-success-subtle text-success">-{{ completedTransaction.discount | currency:'USD':'symbol':'1.2-2' }}</span> | 
                Net Debited: <strong>{{ completedTransaction.netAmount | currency:'USD':'symbol':'1.2-2' }}</strong>
              </div>
            </div>
            <button type="button" class="btn-close" (click)="dismissAlert()" aria-label="Close"></button>
          </div>

          <!-- Error Alert (InfyBankException response) -->
          <div *ngIf="errorMessage" class="alert alert-danger alert-dismissible fade show border-0 rounded-3 d-flex align-items-center" role="alert">
            <i class="bi bi-shield-x fs-4 me-3 text-danger"></i>
            <div class="flex-grow-1">
              <strong>Transfer Rejected by Banking Core</strong>
              <div class="small">{{ errorMessage }}</div>
              <div class="mt-1 small text-muted">Reference: Spring Cloud Gateway &amp; Resilience4j Circuit Breaker Active</div>
            </div>
            <button type="button" class="btn-close" (click)="dismissAlert()" aria-label="Close"></button>
          </div>

          <!-- Form -->
          <form [formGroup]="transferForm" (ngSubmit)="onSubmit()" novalidate>

            <!-- Source Account Selector -->
            <div class="mb-3">
              <label for="sourceAccountNumber" class="form-label fw-semibold">
                Debit Source Account <span class="text-danger">*</span>
              </label>
              <select
                id="sourceAccountNumber"
                class="form-select form-select-lg"
                [ngClass]="{ 'is-invalid': f['sourceAccountNumber'].touched && f['sourceAccountNumber'].errors }"
                formControlName="sourceAccountNumber"
              >
                <option value="" disabled>-- Select Active Account --</option>
                <option *ngFor="let acc of accounts" [value]="acc.accountNumber">
                  {{ acc.accountNumber }} ({{ acc.accountType }}) &mdash; Available Balance: {{ acc.balance | currency:'USD':'symbol':'1.2-2' }}
                </option>
              </select>
              <div *ngIf="f['sourceAccountNumber'].touched && f['sourceAccountNumber'].errors" class="invalid-feedback">
                Please select a source account.
              </div>

              <!-- Available Balance Indicator -->
              <div *ngIf="selectedAccount" class="mt-2 p-2 bg-light rounded-3 d-flex justify-content-between align-items-center">
                <span class="small text-muted">Available Debit Limit:</span>
                <span class="fw-bold text-success">{{ selectedAccount.balance | currency:'USD':'symbol':'1.2-2' }}</span>
              </div>
            </div>

            <!-- Destination Account Input -->
            <div class="mb-3">
              <label for="destinationAccountNumber" class="form-label fw-semibold">
                Beneficiary Destination Account (12 Digits) <span class="text-danger">*</span>
              </label>
              <div class="input-group">
                <span class="input-group-text bg-light border-end-0"><i class="bi bi-person-badge"></i></span>
                <input
                  type="text"
                  id="destinationAccountNumber"
                  maxlength="12"
                  class="form-control border-start-0 font-monospace"
                  [ngClass]="{ 'is-invalid': f['destinationAccountNumber'].touched && f['destinationAccountNumber'].errors }"
                  formControlName="destinationAccountNumber"
                  placeholder="e.g. 100000000003"
                />
                <div *ngIf="f['destinationAccountNumber'].touched && f['destinationAccountNumber'].errors" class="invalid-feedback">
                  <div *ngIf="f['destinationAccountNumber'].errors?.['required']">Beneficiary account number is mandatory.</div>
                  <div *ngIf="f['destinationAccountNumber'].errors?.['pattern']">Must be an exact 12-digit numeric account number.</div>
                </div>
              </div>
            </div>

            <!-- Transfer Amount Input -->
            <div class="mb-3">
              <label for="amount" class="form-label fw-semibold">
                Transfer Amount ($ USD) <span class="text-danger">*</span>
              </label>
              <div class="input-group input-group-lg">
                <span class="input-group-text bg-light border-end-0 fw-bold">$</span>
                <input
                  type="number"
                  step="0.01"
                  min="0.01"
                  id="amount"
                  class="form-control border-start-0 fw-bold fs-4"
                  [ngClass]="{ 'is-invalid': (f['amount'].touched && f['amount'].errors) || hasInsufficientBalance }"
                  formControlName="amount"
                  placeholder="0.00"
                />
                <div *ngIf="f['amount'].touched && f['amount'].errors" class="invalid-feedback">
                  <div *ngIf="f['amount'].errors?.['required']">Transfer amount is mandatory.</div>
                  <div *ngIf="f['amount'].errors?.['min']">Amount must be strictly greater than zero (AC-TXN-01).</div>
                </div>
              </div>
            </div>

            <!-- Dynamic Discount Check Display Card (> 500 Rule Display) -->
            <div class="card border-0 mb-4 overflow-hidden" [ngClass]="isDiscountEligible ? 'bg-success-subtle border-success' : 'bg-light border-light-subtle'">
              <div class="card-body p-3">
                <div class="d-flex align-items-center justify-content-between mb-2">
                  <div class="d-flex align-items-center">
                    <i class="bi" [ngClass]="isDiscountEligible ? 'bi-gift-fill text-success fs-4 me-2' : 'bi-info-circle text-muted fs-5 me-2'"></i>
                    <strong [ngClass]="isDiscountEligible ? 'text-success-emphasis' : 'text-dark'">
                      {{ isDiscountEligible ? '5% Promotional Discount Engine Active!' : 'Promotional Discount Policy (BR-03 & BR-04)' }}
                    </strong>
                  </div>
                  <span class="badge" [ngClass]="isDiscountEligible ? 'bg-success text-white' : 'bg-secondary'">
                    {{ isDiscountEligible ? 'DISCOUNT APPLIED' : 'THRESHOLD: > $500.00' }}
                  </span>
                </div>

                <div class="row g-2 pt-2 border-top border-secondary border-opacity-10 small">
                  <div class="col-4">
                    <span class="text-muted d-block">Gross Amount:</span>
                    <strong class="fs-6">{{ grossAmount | currency:'USD':'symbol':'1.2-2' }}</strong>
                  </div>
                  <div class="col-4">
                    <span class="text-muted d-block">Discount Savings:</span>
                    <strong class="fs-6" [ngClass]="isDiscountEligible ? 'text-success' : 'text-muted'">
                      -{{ discount | currency:'USD':'symbol':'1.2-2' }}
                    </strong>
                  </div>
                  <div class="col-4">
                    <span class="text-muted d-block">Net To Be Debited:</span>
                    <strong class="fs-6 text-primary">{{ netAmount | currency:'USD':'symbol':'1.2-2' }}</strong>
                  </div>
                </div>

                <div *ngIf="!isDiscountEligible && grossAmount > 0" class="mt-2 text-muted x-small">
                  <i class="bi bi-lightbulb text-warning me-1"></i>
                  Transfer more than <strong>$500.00</strong> to automatically unlock a <strong>5% instant cashback discount</strong>!
                </div>
              </div>
            </div>

            <!-- Insufficient Balance Warning Banner -->
            <div *ngIf="hasInsufficientBalance" class="alert alert-warning border-0 rounded-3 mb-4 d-flex align-items-center">
              <i class="bi bi-exclamation-octagon-fill fs-4 me-3 text-warning"></i>
              <div>
                <strong>Insufficient Available Funds</strong>
                <div class="small">
                  The calculated net debit amount (<strong>{{ netAmount | currency:'USD':'symbol':'1.2-2' }}</strong>) exceeds the available balance in your selected account (<strong>{{ selectedAccount?.balance | currency:'USD':'symbol':'1.2-2' }}</strong>).
                </div>
              </div>
            </div>

            <!-- Transfer Button -->
            <div class="d-grid gap-2">
              <button
                type="submit"
                class="btn btn-primary btn-lg fw-semibold shadow-sm d-flex align-items-center justify-content-center"
                [disabled]="isSubmitting || hasInsufficientBalance || transferForm.invalid"
              >
                <span *ngIf="isSubmitting" class="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                <span>{{ isSubmitting ? 'Authorizing Double-Entry Transfer...' : 'Authorize Instant Transfer' }}</span>
              </button>
            </div>

          </form>

        </div>
